mapper.select:
SELECT d.*, e.name AS elder_name, e.phone AS elder_phone FROM device_info d LEFT JOIN device_binding b ON b.device_id = d.id AND b.bind_status = 1 AND b.is_deleted = 0 LEFT JOIN elder_profile e ON b.elder_id = e.id AND e.is_deleted = 0
d.is_deleted = 0
AND d.device_type = #{query.deviceType}
AND d.status = #{query.status}
AND d.online_status = #{query.onlineStatus}
AND b.elder_id = #{query.elderId}
AND (d.device_name LIKE CONCAT('%', #{query.keyword}, '%') OR d.device_sn LIKE CONCAT('%', #{query.keyword}, '%'))
ORDER BY d.create_time DESC
